/* Read-only integration; the metric DOM component is generated by local Qwen. */
(() => {
  'use strict';
  const node=(tag,text)=>{const e=document.createElement(tag);if(text!=null)e.textContent=String(text);return e;};
  const time=t=>t&&Number.isFinite(Date.parse(t))?new Date(t).toLocaleString('pl-PL',{timeZone:'Europe/Warsaw',timeZoneName:'short',fractionalSecondDigits:3}):'—';
  const cutoff=()=>{const s=window.dashboard?.state;return s?.live?(s.hoverAt??Date.now()):(s?.replayAt??Date.parse(s?.data?.cutoff));};
  document.addEventListener('DOMContentLoaded',()=>{
    const panel=node('section');panel.id='surge-hunter-panel';panel.className='panel entry-timing-panel';
    panel.append(node('span','EXP-0018.1 / OBSERWACJA I FORENSYKA'),node('h2','HIGH TEMPTATION — SURGE HUNTER'));
    const status=node('p'),cards=node('div'),details=node('div'),selector=node('select'),zoom=node('select'),retro=node('input');
    cards.className='entry-timing-metrics';retro.type='checkbox';const label=node('label',' Analiza retrospektywna (późniejsza wiedza) ');label.prepend(retro);
    selector.setAttribute('aria-label','Zdarzenie Surge Hunter');zoom.setAttribute('aria-label','Okno czasowe');
    [[300,'±5 min'],[60,'±60 s'],[10,'±10 s'],[3,'±3 s']].forEach(([value,text])=>{const o=node('option',text);o.value=value;zoom.append(o);});
    panel.append(status,cards,label,selector,zoom,details);document.querySelector('.footer')?.before(panel);
    let catalog=null,live=null,chosen='WELLINGTON',key='',busy=false,error=false;
    function chart(rows,center,well){
      const span=Number(zoom.value)||300,base=Date.parse(center),ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 1000 260');svg.setAttribute('role','img');svg.setAttribute('aria-label','YES i NO: tylko zapisane punkty bid i ask; różne zegary transakcji');
      const add=(tag,attrs,text)=>{const e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,String(v)));if(text!=null)e.textContent=text;svg.append(e);return e;};
      const x=t=>55+(Date.parse(t)-base+span*1000)/(span*2000)*880;
      if(!Number.isFinite(base))return svg;
      [0,.5,1].forEach(p=>add('text',{x:5,y:200-p*160,fill:'#a9bbca','font-size':12},p.toFixed(2)));
      [-span,0,span].forEach(s=>add('text',{x:55+(s+span)/(2*span)*880,y:248,fill:'#a9bbca','font-size':12},`${s}s`));
      for(const r of rows){if(!r.received_at||!Number.isFinite(Date.parse(r.received_at))||Math.abs(Date.parse(r.received_at)-base)>span*1000)continue;for(const [field,color] of r.outcome==='no'?[['bid','#41cec2'],['ask','#e7ae55']]:[['bid','#a78bea'],['ask','#75aefa']]){const p=r[field];if(typeof p!=='number'||!Number.isFinite(p))continue;const dot=add('circle',{cx:x(r.received_at),cy:200-p*160,r:2.5,fill:color});const tip=document.createElementNS(ns,'title');tip.textContent=`${r.outcome} ${field} ${p} · ${time(r.received_at)}`;dot.append(tip);}if(r.kind==='WS_TRADE'&&r.price!=null)add('text',{x:x(r.received_at),y:25,fill:'#eee','font-size':11},`${r.side??''} WS`);}
      if(well){for(const j of well.exact_ws_transaction_joins??[]){if(Math.abs(Date.parse(j.received_at)-base)>span*1000)continue;const xx=x(j.received_at);add('line',{x1:xx,x2:xx,y1:35,y2:205,stroke:'#f38aa1','stroke-dasharray':'3 3'});add('text',{x:xx,y:j.side==='BUY'?218:232,fill:'#f38aa1','font-size':11},`${j.side} WS/hash`);}}
      add('line',{x1:495,x2:495,y1:35,y2:205,stroke:'#b3bec8','stroke-dasharray':'6 3'});add('text',{x:500,y:40,fill:'#b3bec8','font-size':11},well?'Czas źródłowy API/bloku':'Detekcja zdarzenia');
      return svg;
    }
    function render(force=false){
      const at=cutoff(),auditKnown=catalog&&(retro.checked||Date.parse(catalog.published_at)<=at),liveKnown=live&&(retro.checked||Date.parse(live.published_at)<=at);
      const data=liveKnown&&(!auditKnown||Date.parse(live.published_at)>=Date.parse(catalog.published_at))?live:auditKnown?catalog:null,newKey=`${at>0}|${auditKnown}|${liveKnown}|${chosen}|${zoom.value}|${retro.checked}|${catalog?.published_at}|${live?.published_at}|${error}`;
      if(!force&&key===newKey)return;key=newKey;cards.replaceChildren();details.replaceChildren();selector.replaceChildren();
      if(!data){status.textContent='Brak raportu dostępnego w wybranym czasie. Późniejsza wiedza niedostępna.';return;}
      status.textContent=`${data.mode} · ${data.status??data.session?.status??'ZAKOŃCZONE SESJE'} · ${time(data.published_at)}${Date.now()-Date.parse(data.published_at)>120000?' · NIEŚWIEŻY RAPORT':''}${error?' · BŁĄD ODCZYTU':''}`;
      for(const [label,value] of [['Kontrakty',data.session?.contracts],['Tokeny YES/NO',data.session?.tokens],['Zdarzenia progowe',data.summary?.surges],['Wejścia tradera',data.summary?.entries],['Potwierdzone fille badania',data.summary?.supported_fills],['Dopasowane kontrole',data.summary?.matched_controls]])cards.append(window.michuplSurgeMetric(label,value));
      details.append(node('p','SHADOW ONLY. Zdarzenie ≠ możliwość wykonania ≠ fill ≠ zysk. PONG nie potwierdza świeżości książki; po zakończeniu sesji stare kwoty nie są bieżącą płynnością.'));
      const options=[...(auditKnown?[['WELLINGTON','Wellington — rekonstrukcja historyczna']]:[]),...(data.events??[]).map(e=>[e.surge_id,`${e.kind} ${e.outcome??''} ${time(e.received_at)}`])];
      for(const [v,t] of options){const o=node('option',t);o.value=v;selector.append(o);}if(!options.some(o=>o[0]===chosen))chosen=options[0]?.[0]??'';selector.value=chosen;
      if(chosen==='WELLINGTON'&&auditKnown){const w=catalog.wellington;details.append(node('p',`RETROSPEKTYWNE: ${w.classification}. Wyzwalacz: ${w.trigger_causality}. Publiczny BUY po dokładnym hash pojawił się przed wzrostem bidu.`),chart(w.timeline,w.target,w));const table=node('table');table.className='data-table';const head=node('tr');['Odbiór lokalny Warszawa','Typ','Strona','Bid','Ask','Cena transakcji'].forEach(t=>head.append(node('th',t)));table.append(head);for(const r of w.timeline.filter(r=>Math.abs(Date.parse(r.received_at)-Date.parse(w.target))<=10000)){const tr=node('tr');[time(r.received_at),r.kind,r.outcome,r.bid,r.ask,r.price].forEach(v=>tr.append(node('td',v??'—')));table.append(tr);}const scroll=node('div');scroll.className='table-scroll';scroll.append(table);details.append(scroll);}else{const e=(data.events??[]).find(e=>e.surge_id===chosen);if(e){details.append(chart([e.before_quote,e.after_quote].filter(Boolean),e.received_at,null));const d=node('details');d.append(node('summary','Dowody, płynność i założenia'),node('pre',JSON.stringify(e,null,2)));details.append(d);}else details.append(node('p','Brak zdarzeń spełniających progi. Nie oznacza to braku ruchów na wszystkich rynkach.'));}
      details.append(node('p','NO bid: turkus · NO ask: złoto · YES bid: fiolet · YES ask: niebieski. Bez interpolacji. Zmniejszenie okna może ukryć zdarzenia sprzed czasu bloku/API. Statystyki lustrzanych zmian nie są niezależnymi próbami.'));
    }
    async function refresh(){if(busy)return;busy=true;try{for(const [path,set] of [['surge_hunter_summary.json',v=>catalog=v],['surge_hunter_live.json',v=>live=v]]){const c=new AbortController(),timer=setTimeout(()=>c.abort(),5000);try{const r=await fetch('/static/'+path,{cache:'no-store',signal:c.signal});if(r.ok){const d=await r.json();if(Number.isFinite(Date.parse(d.published_at)))set(d);}}finally{clearTimeout(timer);}}error=false;}catch{error=true;}finally{busy=false;render(true);}}
    selector.addEventListener('change',()=>{chosen=selector.value;render(true);});zoom.addEventListener('change',()=>render(true));retro.addEventListener('change',()=>render(true));refresh();setInterval(refresh,60000);setInterval(()=>render(),1000);
  });
})();
